<?php $base='/research/'.$r['slug'];$project=wf_project($r['id']);$tasks=wf_tasks($r['id']);usort($tasks,fn($a,$b)=>(array_search($a['state'],['Ready','Waiting','Completed','Superseded'])<=>array_search($b['state'],['Ready','Waiting','Completed','Superseded'])));$ready=array_values(array_filter($tasks,fn($t)=>$t['state']==='Ready'));$held=wf_quarantine($r['id']);$paused=$held||in_array($r['status'],['Blocked','Needs Clarification','Paused','Archived — Inactive','Solved'],true); ?>
<div class="workflow-heading"><a class="back" href="<?=e($base)?>">← Research brief</a><h1><?=e($r['title'])?></h1><p><?=status_badge($held?'Awaiting admin decision':$r['status'])?><?php if($project): ?> · Planning round <?=e($project['round_no'])?><?php endif ?></p>
<div class="actions primary-actions"><?php if($r['status']==='Review Complete'): ?><a class="button" href="#research-findings">Read findings</a><?php endif ?><?php if($ready&&!$paused): ?><a class="button" href="<?=e($base)?>/tasks/<?=e($ready[0]['id'])?>"><?=e($ready[0]['kind']==='planning'?'Help plan this research':'Help with the next task')?></a><?php endif ?><a class="button secondary" href="<?=e($base)?>/ledger">Catch up · UTC ledger</a><a class="button secondary" href="<?=e($base)?>/package.json">Full context package</a></div></div>
<?php include __DIR__.'/tool-catalogue.php'; ?>
<?php if($paused): ?><section class="notice"><h2><?=e($held?'Packet quarantined — awaiting admin':'Waiting for a response')?></h2><?php if($held): ?><p>No task results can advance until an administrator approves or rejects the packet. <a href="<?=e($base)?>/results/<?=e($held['id'])?>">View packet status</a></p><?php else: ?><p>The original submitter can respond through their private management link. An administrator can also help. No new tasks can advance while this project is paused.</p><?php endif ?><?php if($project['blocker_id']??null): $b=one("SELECT * FROM workflow_submissions WHERE id=? AND visibility='public'",[$project['blocker_id']]); if($b): ?><p><strong><?=e($b['reason'])?></strong></p><?=prose($b['next_action'])?><a href="<?=e($base)?>/results/<?=e($b['id'])?>">Read the complete blocker</a><?php endif; endif ?></section><?php endif ?>
<p class="fine">Bring your own AI. Accepted task results advance automatically; acceptance does not establish scientific truth. Review independence and model provenance are self-reported.</p>
<?php include __DIR__.'/workflow-findings.php';include __DIR__.'/research-artifacts.php'; ?>
<div class="task-grid"><?php foreach($tasks as $t): ?><article class="task-card"><div class="row-top"><span class="category"><?=e(!empty($t['builds_tool'])?'tool build':$t['kind'])?></span><span class="status"><?=e($t['state'])?></span></div><h2><a href="<?=e($base)?>/tasks/<?=e($t['id'])?>"><?=e($t['title'])?></a></h2><p><?=e(research_excerpt($t['objective'],240))?></p><p class="fine"><strong>Deliverable:</strong> <?=e(research_excerpt($t['deliverable'],180))?></p><?php if(json_decode($t['dependencies'],true)): ?><p class="fine">Depends on: <?php foreach(json_decode($t['dependencies'],true) as $dep): $dt=wf_task($r['id'],$dep); ?><a href="<?=e($base)?>/tasks/<?=e($dep)?>"><?=e($dt['title'])?></a> · <?php endforeach ?></p><?php endif ?><a class="text-action" href="<?=e($base)?>/tasks/<?=e($t['id'])?>"><?=e($t['state']==='Ready'&&!$paused?'Open task →':'View task & results →')?></a></article><?php endforeach ?></div>
<?php if(!$tasks): ?><p>This topic has no active planning task yet. Initial topic approval starts the workflow.</p><?php endif ?>
<?php if($r['status']==='Review Complete'): ?><section class="form-panel" id="request-review"><h2>Continue independent verification</h2><p>A completed cycle can still be challenged. Explain what needs checking; a new review task opens automatically.</p><form method="post"><?=csrf()?><?php field('Reason for another review','reason','','textarea',true);field('Display name','display_name');terms(); ?><button>Open another review task</button></form></section><?php endif ?>
<section class="section"><h2>Latest updates</h2><?php foreach(array_slice(array_reverse(wf_ledger($r['id'])),0,5) as $event): ?><article class="ledger-entry"><time><?=e($event['created_at'])?> UTC</time><h3><?=e($event['action'])?> · <?=e($event['new_state'])?></h3><p><?=e($event['reason'])?></p><p class="fine">Next: <?=e($event['next_action']?:'See ready tasks and the full ledger.')?></p></article><?php endforeach ?></section>
